package com.codepilot1c.core.tools.development;
import java.util.*;import java.util.concurrent.CompletableFuture;
import com.google.gson.*;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.edt.development.*;
import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
@ToolMeta(name="edt_ui_run",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtUiRunTool extends AbstractTool {
 public String getDescription(){return "Run verified direct UI batches via edt.run op=ui. Start requires project/base_uuid/idempotency_key and1..16 typed steps: exact expected_window, expect for mutations and final assertion; calendar steps need expect.fields on a separate bound scalar field. Uses EQUAL-bound owned TestClient and managed Python. To share a client within one task: first start auto_cleanup=false; later starts use new keys plus reuse_from_ui_run_id of that original successful run. Fresh UUID/EQUAL/kind/process/channel checks; no replacement launch. Borrowers close only their session; cleanup the owner at task end via cleanup_preview then cleanup with expected_plan_sha256. Default auto_cleanup=true is one-shot. Unknown outcomes block reuse/replay/executor switch. start/status/wait return compact outcomes/counts and ready-to-call next_call/details_call. Follow wait(next_call) on the SAME run instead of polling job then status; timeout_ms0..25000(default20000) is observation only. Terminal failures/unknowns point to original details, never restart. A passed retained client has no automatic cleanup/reuse call. Status does not include full logs/timings/values; details retains full results/timings before cleanup. capture=on_failure(default)|final|final_and_failure|none: owned windows only. Slow forms: operation_timeout_s5..300 overall batch (default60), per-step wait_timeout_ms within budget (explicit condition default10s), startup readiness10..180s (default90). Native handles BSL/data, can seed/assert same verified base alongside UI; Vanessa for unsupported UI or explicit scenarios. No DB update, trust change, arbitrary BSL or business-data cleanup. Wait original job via edt_operation_status; never resubmit a mutation to poll.";}
 public String getParameterSchema(){var schema=JsonParser.parseString("""
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["start","resume","status","wait","details","cleanup_preview","cleanup"]},"project":{"type":"string"},"base_uuid":{"type":"string"},"idempotency_key":{"type":"string","maxLength":256},"client_kind":{"enum":["thin","thick"],"default":"thin"},"readiness_timeout_s":{"type":"integer","minimum":10,"maximum":180,"default":90},"capture":{"enum":["none","final","on_failure","final_and_failure"],"default":"on_failure"},"auto_cleanup":{"type":"boolean","default":true},"reuse_from_ui_run_id":{"type":"string","pattern":"^ui-[a-f0-9]{64}$"},"operation_timeout_s":{"type":"integer","minimum":5,"maximum":300,"default":60},"ui_run_id":{"type":"string","pattern":"^ui-[a-f0-9]{64}$"},"timeout_ms":{"type":"integer","minimum":0,"maximum":25000,"default":20000},"expected_plan_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """).getAsJsonObject();schema.getAsJsonObject("properties").add("steps",JsonParser.parseString(new EdtFormActionTool().getParameterSchema()).getAsJsonObject().getAsJsonObject("properties").get("steps"));return schema.toString();}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.supplyAsync(()->{try{for(String tool:UiRunBackend.dependencies())UiRunBackendPermission.check(tool);var s=UiRunService.workspace();var a=new LinkedHashMap<>(p.getRaw());String action=p.requireString("action");a.remove("action");Object out;
  if(action.equals("start"))out=s.start(a);
  else{if(!(action.equals("cleanup")?Set.of("ui_run_id","expected_plan_sha256"):action.equals("wait")?Set.of("ui_run_id","timeout_ms"):Set.of("ui_run_id")).containsAll(a.keySet()))throw new IllegalArgumentException("Field does not apply to action");String id=p.requireString("ui_run_id");out=switch(action){case "resume"->s.resume(id);case "status"->s.status(id);case "wait"->s.waitFor(id,AgentResponses.integer(a,"timeout_ms",20000,0,25000));case "details"->s.details(id);case "cleanup_preview"->s.cleanupPreview(id);case "cleanup"->Map.of("job_id",BackgroundJobRegistry.getInstance().startJob("ui-run-cleanup",()->new Gson().toJson(s.cleanup(id,p.requireString("expected_plan_sha256")))),"ui_run_id",id,"next_tool","edt_operation_status");default->throw new IllegalArgumentException("Unknown UI run action");};}
  if(Set.of("start","resume","status","wait").contains(action)){@SuppressWarnings("unchecked") var result=(Map<String,Object>)out;out=WorkflowReplies.ui(result);}
  if(action.equals("cleanup")){@SuppressWarnings("unchecked") var result=new LinkedHashMap<>((Map<String,Object>)out);if(result.get("job_id") instanceof String job)result.put("next_call",WorkflowReplies.job(job));out=result;}
  return ToolResult.success(new GsonBuilder().serializeNulls().create().toJson(out));
 }catch(Exception e){return ToolResult.failure("edt_ui_run: "+(e instanceof IllegalArgumentException?e.getMessage():e.getClass().getSimpleName()+"; inspect original run and contract"));}});}
 private static class UiRunBackendPermission {static void check(String tool){var cfg=com.codepilot1c.core.mcp.host.McpHostConfigStore.getInstance().load();if(cfg.getMutationPolicy()!=com.codepilot1c.core.mcp.host.McpHostConfig.MutationPolicy.ALLOW||!new com.codepilot1c.core.mcp.host.DefaultMcpToolExposurePolicy(cfg).isExposed(tool))throw new IllegalStateException("Dependency unavailable");}}
}
